import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useTheme } from '../context/ThemeContext';
import { useLanguageContext } from '../context/LanguageContext';

const NotificationModal = ({ isOpen, onClose }) => {
  const { colors, isDarkMode } = useTheme();
  const { t } = useLanguageContext();

  const notifications = [
    {
      id: 1,
      icon: '🆕',
      title: t('notif.updateTitle'),
      message: t('notif.updateMsg'),
      time: '2 ساعت پیش',
      color: '#4CAF50',
    },
    {
      id: 2,
      icon: '🎉',
      title: t('notif.eventTitle'),
      message: t('notif.eventMsg'),
      time: '5 ساعت پیش',
      color: '#FF9800',
    },
    {
      id: 3,
      icon: '📋',
      title: t('notif.ruleTitle'),
      message: t('notif.ruleMsg'),
      time: '1 روز پیش',
      color: '#2196F3',
    },
    {
      id: 4,
      icon: '🎮',
      title: 'تورنمنت هفتگی',
      message: 'ثبت‌نام تورنمنت این هفته شروع شد!',
      time: '2 روز پیش',
      color: '#9C27B0',
    },
    {
      id: 5,
      icon: '⭐',
      title: 'عضو ویژه هفته',
      message: 'تبریک به عضو برتر این هفته! 🎉',
      time: '3 روز پیش',
      color: '#FFD700',
    },
  ];

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={onClose}
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0,0,0,0.7)',
            backdropFilter: 'blur(8px)',
            zIndex: 2000,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: '20px',
          }}
        >
          <motion.div
            initial={{ scale: 0.8, opacity: 0, y: 50 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.8, opacity: 0, y: 50 }}
            transition={{ type: 'spring', stiffness: 300, damping: 25 }}
            onClick={(e) => e.stopPropagation()}
            style={{
              background: colors.primary,
              border: `1px solid ${colors.border}`,
              borderRadius: '24px',
              padding: '30px',
              maxWidth: '600px',
              width: '100%',
              maxHeight: '80vh',
              overflow: 'hidden',
              display: 'flex',
              flexDirection: 'column',
              boxShadow: `0 20px 60px ${isDarkMode ? 'rgba(0,0,0,0.5)' : 'rgba(0,0,0,0.2)'}`,
              direction: 'rtl',
            }}
          >
            <div style={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              marginBottom: '25px',
              paddingBottom: '15px',
              borderBottom: `1px solid ${colors.border}`,
            }}>
              <h2 style={{ color: colors.text, fontSize: '1.5rem', fontWeight: 700, margin: 0 }}>
                🔔 {t('notif.title')}
              </h2>
              <motion.button
                whileHover={{ scale: 1.1, rotate: 90 }}
                whileTap={{ scale: 0.9 }}
                onClick={onClose}
                style={{
                  background: colors.card,
                  border: `1px solid ${colors.border}`,
                  color: colors.text,
                  width: '36px',
                  height: '36px',
                  borderRadius: '12px',
                  cursor: 'pointer',
                  fontSize: '1.1rem',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                }}
              >
                ✕
              </motion.button>
            </div>

            <div style={{ overflowY: 'auto', flex: 1, paddingRight: '5px' }}>
              {notifications.map((notif, index) => (
                <motion.div
                  key={notif.id}
                  initial={{ opacity: 0, x: 30 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: index * 0.1 }}
                  whileHover={{ x: -5, background: `${notif.color}10`, borderColor: `${notif.color}40` }}
                  style={{
                    background: colors.card,
                    border: `1px solid ${colors.border}`,
                    borderRadius: '16px',
                    padding: '18px',
                    marginBottom: '12px',
                    transition: 'all 0.3s ease',
                    cursor: 'pointer',
                  }}
                >
                  <div style={{ display: 'flex', gap: '14px', alignItems: 'flex-start' }}>
                    <div style={{
                      background: `${notif.color}20`,
                      width: '44px',
                      height: '44px',
                      borderRadius: '14px',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      fontSize: '1.3rem',
                      flexShrink: 0,
                    }}>
                      {notif.icon}
                    </div>
                    <div style={{ flex: 1 }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '6px' }}>
                        <h4 style={{ color: colors.text, fontSize: '1rem', fontWeight: 600, margin: 0 }}>
                          {notif.title}
                        </h4>
                        <span style={{ fontSize: '0.75rem', color: colors.textSecondary, whiteSpace: 'nowrap' }}>
                          {notif.time}
                        </span>
                      </div>
                      <p style={{ color: colors.textSecondary, fontSize: '0.9rem', margin: 0, lineHeight: 1.6 }}>
                        {notif.message}
                      </p>
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>

            <motion.button
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
              onClick={onClose}
              style={{
                background: colors.accent,
                border: 'none',
                color: '#fff',
                padding: '14px',
                borderRadius: '14px',
                cursor: 'pointer',
                fontSize: '1rem',
                fontWeight: 600,
                marginTop: '20px',
                width: '100%',
              }}
            >
              بستن
            </motion.button>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default NotificationModal;
